 protected void onDestroy(){recoveryPrompt.close();super.onDestroy();}
 private void requestStart(){recoveryPrompt.beforeStart(this,this::requestReviewedStart);}
 private void requestReviewedStart(){if(selectedSteps&&!IndoorStepService.permitted(this)&&Build.VERSION.SDK_INT>=29){requestPermissions(new String[]{android.Manifest.permission.ACTIVITY_RECOGNITION},104);return;}if(Build.VERSION.SDK_INT>=33&&checkSelfPermission(android.Manifest.permission.POST_NOTIFICATIONS)!=android.content.pm.PackageManager.PERMISSION_GRANTED){requestPermissions(new String[]{android.Manifest.permission.POST_NOTIFICATIONS},103);return;}beginCountdown(selectedKind,selectedGoal);}
 public void onRequestPermissionsResult(int request,String[] permissions,int[] result){super.onRequestPermissionsResult(request,permissions,result);if(request==104){if(!IndoorStepService.permitted(this)){status.setText("Step counting needs Physical activity permission. Tap Start to retry, or turn off Count phone steps to explicitly record time only.");return;}requestReviewedStart();}else if(request==103)beginCountdown(selectedKind,selectedGoal);}
 private void calibrate(){LinearLayout f=new LinearLayout(this);f.setOrientation(LinearLayout.VERTICAL);EditText distance=entry(f,"Known machine distance · km",""),count=entry(f,"Detected steps over that same distance · minimum 100","");Spinner type=new Spinner(this);type.setAdapter(new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,List.of("Walk","Run")));f.addView(type);AlertDialog dialog=new AlertDialog.Builder(this).setTitle("Your step length").setMessage("Use a steady session with the phone carried on your body. One step, not a two-step stride. Calibration applies to future sessions.").setView(f).setNegativeButton("Cancel",null).setPositiveButton("Save",null).create();dialog.setOnShowListener(x->dialog.getButton(-1).setOnClickListener(v->{try{String kind=type.getSelectedItem().toString();double length=StepEstimate.length(Double.parseDouble(distance.getText().toString()),Long.parseLong(count.getText().toString()),kind);synchronized(RunStore.LOCK){JSONObject d=store.v103(),lengths=d.optJSONObject("stepLengths");if(lengths==null)lengths=new JSONObject();lengths.put(kind,length);d.put("stepLengths",lengths);store.v103(d);}dialog.dismiss();status.setText(String.format(Locale.ROOT,"%s step length saved: %.2f m · applies to future sessions",kind,length));}catch(Exception e){Toast.makeText(this,UserErrors.message(e),Toast.LENGTH_LONG).show();}}));dialog.show();}
 private void beginCountdown(String kind,int goal){countdown=3;timer.setText("3");Runnable next=new Runnable(){public void run(){if(--countdown>0){timer.setText(""+countdown);handler.postDelayed(this,1000);return;}try{IndoorState.start(IndoorActivity.this,kind,goal,getIntent().getStringExtra("planned"),selectedSteps);show();}catch(Exception e){status.setText(UserErrors.message(e));}}};handler.postDelayed(next,1000);}
